import { request, repository } from './storage.js';
const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const statusNames = {pending:'Pendente de validação',waiting:'Em espera',option:'Em opção prioritária',confirmed:'Confirmado',cancelled:'Cancelado'};
const resorts = {cs:'Costa do Sauípe',rq:'Rio Quente'};
const phases = {setup:'Montagem',event:'Evento',teardown:'Desmontagem'};
const months = ['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'];
const today = new Date();
const state = {user:null,view:'calendar',year:Math.min(2028,Math.max(2026,today.getFullYear())),month:today.getMonth(),resort:'all',search:'',status:'',mode:matchMedia('(max-width:760px)').matches?'list':'grid',catalog:[],resources:[],bookings:[],occupying:[],days:[],calendar:[],users:[],online:true,lastSync:'',reportFrom:'2026-01-01',reportTo:'2028-12-31'};
let modalDirty=false, loading=false, refreshNumber=0, toastTimer;
const fmt = d => String(d).slice(0,10).split('-').reverse().join('/');
const normalized = v => String(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const option = (v,t,current) => `<option value="${esc(v)}" ${String(v)===String(current)?'selected':''}>${esc(t)}</option>`;
const pill = s => `<span class="status-pill status-${s}">${statusNames[s]}</span>`;
const btn = (action,label,attrs='',primary=false) => `<button type="button" class="btn ${primary?'primary':''}" data-action="${action}" ${attrs}>${label}</button>`;
const passwordField = (label,name,autocomplete,min=0,max=10) => `<div class="password-input"><label for="password-${name}">${label}</label><div class="password-control"><input id="password-${name}" name="${name}" type="password" autocomplete="${autocomplete}" required ${min?`minlength="${min}"`:''} maxlength="${max}"><button type="button" class="password-toggle" data-action="toggle-password" aria-controls="password-${name}" aria-label="Mostrar ${label.toLowerCase()}" aria-pressed="false">Mostrar</button></div></div>`;
const resourceName = id => state.resources.find(r=>r.id===id)?.name || id;
const resortName = id => resorts[id] || 'Empreendimento não definido';
function toast(text,error=false){ const el=$('#toast');el.textContent=text;el.className=`visible ${error?'error':''}`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='',error?9000:4000); }
function errorView(error){toast(error.message,true);if(error.status===401){state.user=null;closeModal(true);boot();}}
function range(){ const prefix=`${state.year}-${String(state.month+1).padStart(2,'0')}`;return {from:`${prefix}-01`,to:`${prefix}-${new Date(state.year,state.month+1,0).getDate()}`}; }
function queryString(full=false){let r=full?{from:'2026-01-01',to:'2028-12-31'}:range();if(state.view==='reports')r={from:state.reportFrom,to:state.reportTo};return new URLSearchParams({...r,resort:state.resort,status:state.status,search:state.search}).toString();}
function closeModal(force=false){if(!force&&modalDirty&&!confirm('Descartar as alterações não salvas deste formulário?'))return false;$('#editor').close();$('#editor').innerHTML='';modalDirty=false;return true;}
function modal(title,body,actions='',wide=false){if($('#editor').open&&!closeModal())return false;const el=$('#editor');el.className=wide?'wide-modal':'';el.innerHTML=`<div class="modal-head"><h2 id="editor-title">${title}</h2>${btn('close','×','aria-label="Fechar"')}</div><div class="modal-body">${body}</div>${actions?`<div class="modal-actions">${actions}</div>`:''}`;modalDirty=false;el.showModal();el.oncancel=e=>{e.preventDefault();closeModal();};el.oninput=()=>modalDirty=true;return true;}
function bindForm(selector,handler){const form=$(selector);form.onsubmit=async e=>{e.preventDefault();if(!form.reportValidity())return;const submit=form.querySelector('[type=submit]')||document.querySelector(`[form="${form.id}"]`);if(submit)submit.disabled=true;const err=form.querySelector('.form-error');if(err)err.textContent='';try{await handler(new FormData(form));}catch(error){if(err)err.textContent=error.message;else errorView(error);}finally{if(submit)submit.disabled=false;}};}
async function boot(){try{const session=await repository.session();state.user=session.user;state.qa=session.qa_mode;state.authMode=session.auth_mode;if(!state.user){if(state.authMode==='entra')corporateLoginScreen();else loginScreen(session);return;}await refresh();}catch(error){$('#app').innerHTML=`<main class="loading-screen"><h1>Não foi possível abrir a agenda</h1><p class="notice">${esc(error.message)}</p>${btn('retry','Tentar novamente')}</main>`;}}
function corporateLoginScreen(){const failed=new URLSearchParams(location.search).has('login_error');$('#app').innerHTML=`<main class="login-shell"><section class="login-story"><div class="aviva-brand"><img src="/static/assets/aviva-logo.png" alt="Aviva" width="427" height="200"></div><div class="brand-caption">Costa do Sauípe · Rio Quente</div><div class="login-copy"><div class="eyebrow">COMERCIAL MICE & OPERAÇÃO</div><h1>Um espaço para<br>cada encontro.<br><em>Uma agenda<br>para todos.</em></h1><p>Consulte os espaços, organize os bloqueios<br>e acompanhe cada negociação.</p></div><div class="story-footer">CALENDÁRIO DE ESPAÇOS <span>2026 — 2028</span></div></section><section class="login-main"><div class="login-form-wrap"><span class="tiny-label">AGENDA COMPARTILHADA</span><h2>Seu próximo evento<br>começa aqui.</h2><p class="muted">Entre com sua conta corporativa.</p>${failed?'<p class="notice" role="alert">Não foi possível concluir o acesso. Confirme com a equipe responsável se sua conta está autorizada.</p>':''}<a class="btn primary login-submit" href="/api/entra/login">Entrar com Microsoft</a></div><footer>Calendário provisório de salas <span>2026 · 2027 · 2028</span></footer></section></main>`;}
function loginScreen(session){const setup=session.setup_required;$('#app').innerHTML=`<main class="login-shell"><section class="login-story"><div class="aviva-brand"><img src="/static/assets/aviva-logo.png" alt="Aviva" width="427" height="200"></div><div class="brand-caption">Costa do Sauípe · Rio Quente</div><div class="login-copy"><div class="eyebrow">COMERCIAL MICE & OPERAÇÃO</div><h1>Um espaço para<br>cada encontro.<br><em>Uma agenda<br>para todos.</em></h1><p>Consulte os espaços, organize os bloqueios<br>e acompanhe cada negociação.</p></div><div class="story-footer">CALENDÁRIO DE ESPAÇOS <span>2026 — 2028</span></div></section><section class="login-main"><div class="login-form-wrap"><span class="tiny-label">AGENDA COMPARTILHADA</span><h2>${setup?'Vamos preparar<br>seu primeiro acesso.':'Seu próximo evento<br>começa aqui.'}</h2><p class="muted">${setup?'Crie sua conta individual para administrar este ambiente.':'Entre com sua conta individual.'}</p><form id="login-form">${setup?'<label>Seu nome<input name="name" autocomplete="name" required maxlength="120"></label><label>Equipe<select name="team_id"><option value="commercial">Comercial MICE</option><option value="operations">Operacional</option></select></label>':''}<label>Usuário<input name="username" autocomplete="username" required minlength="3" maxlength="64" placeholder="Usuário ou e-mail cadastrado" aria-describedby="username-help" autofocus></label><p id="username-help" class="form-help">${setup?'Defina seu usuário sem espaços. Você pode usar seu e-mail.':'Informe o usuário definido no cadastro, que pode ser seu e-mail. O nome completo não é o login.'}</p>${passwordField('Senha','password',setup?'new-password':'current-password',setup?15:0,setup?128:256)}<p class="form-help">Dica de senha: novas senhas devem ter de 15 a 128 caracteres.</p><div class="form-error" role="alert"></div><button class="btn primary login-submit" type="submit" ${setup&&!session.local_setup_allowed?'disabled':''}>${setup?'Criar primeiro acesso':'Entrar na agenda'}</button></form>${setup?'<div class="notice">A primeira conta administra cadastros, acessos e a fila. Cada equipe continua editando apenas seus próprios bloqueios. Use uma senha de 15 a 128 caracteres.</div>':'<p class="local-note">Use seu usuário e sua senha cadastrados para acessar a agenda.</p>'}</div><footer>Calendário provisório de salas <span>2026 · 2027 · 2028</span></footer></section></main>`;bindForm('#login-form',async fields=>{const data=Object.fromEntries(fields);const result=setup?await request('/setup',{method:'POST',body:data}):await repository.login(data);state.user=result.user;state.view='calendar';state.status='';state.search='';state.resort='all';await refresh();});}
async function refresh(quiet=false){if(!['all','cs','rq'].includes(state.resort))state.resort='all';if(!state.user||loading)return;if(quiet&&($('#editor').open||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName)))return;loading=true;const serial=++refreshNumber;try{const catalog=await repository.catalog();state.catalog=catalog.configurations;state.resources=catalog.resources;state.sourceCount=catalog.source_count;if(state.view==='calendar'){const data=await request(`/calendar?${queryString()}`);state.calendar=data.configurations;state.days=data.days;state.bookings=data.bookings;state.occupying=data.occupying_bookings;}else if(['queue','reports'].includes(state.view)){state.bookings=(await request(`/bookings?${queryString(true)}`)).bookings;}else if(state.view==='users'){state.users=(await request('/users')).users;}state.online=true;state.lastSync=new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});if(serial===refreshNumber)render();}catch(error){state.online=false;if(!quiet)errorView(error);const el=$('#sync');if(el){el.className='sync-state offline';el.textContent='Sem conexão · dados podem estar desatualizados';}}finally{loading=false;}}
function sidebar(){const nav=[['calendar','Calendário'],['queue','Solicitações & fila'],['catalog','Salas & espaços'],['reports','Relatórios']];if(state.user.can_manage_users)nav.push(['users','Pessoas & acessos']);return `<aside class="agenda-sidebar"><div class="aviva-brand"><img src="/static/assets/aviva-logo.png" alt="Aviva" width="427" height="200"></div><div class="brand-caption">Gestão de espaços</div><div class="resort-wordmark">Costa do Sauípe<br>Rio Quente Resorts</div><nav class="agenda-nav" aria-label="Navegação principal">${nav.map(([id,label])=>`<button data-action="navigate" data-view="${id}" class="${state.view===id?'current':''}" ${state.view===id?'aria-current="page"':''}>${label}</button>`).join('')}</nav><div class="sidebar-note">Uma base compartilhada.<br>Cada equipe cuida dos seus bloqueios.</div><div class="sidebar-user"><strong>${esc(state.user.name)}</strong><small>${state.user.team_id==='commercial'?'Comercial MICE':'Operacional'}</small>${state.authMode==='entra'?'':'<button data-action="password">Alterar minha senha</button>'}<button data-action="logout">Sair da agenda ↗</button></div></aside>`;}
function render(){const titles={calendar:['Calendário de espaços','Veja a ocupação e acompanhe as solicitações, dia a dia.'],queue:['Solicitações & fila','Ordem de entrada, com prioridade concedida manualmente.'],catalog:['Salas & espaços','Consulte os espaços e valide suas composições.'],reports:['Relatórios','Consulte e compartilhe os bloqueios do período selecionado.'],users:['Pessoas & acessos','Contas individuais, equipes e responsabilidades bem definidas.']};const [title,subtitle]=titles[state.view];const unvalidated=state.catalog.filter(c=>!c.validated).length;$('#app').innerHTML=`<div class="agenda-shell">${sidebar()}<div class="agenda-main"><header class="agenda-top"><span>Espaços de eventos <span aria-hidden="true">/</span> ${title}</span><div><span id="sync" class="sync-state ${state.online?'':'offline'}">${state.online?`Atualizado às ${state.lastSync}`:'Sem conexão · consulta desatualizada'}</span> <button class="icon-btn" data-action="refresh" aria-label="Atualizar agenda">↻</button><button class="icon-btn" data-action="logout" aria-label="Sair">↗</button></div></header><main class="agenda-content">${state.qa?'<div class="notice qa-banner">AMBIENTE DE TESTES · Dados e validações fictícios, isolados da base operacional.</div>':''}<div class="agenda-heading"><div><div class="agenda-eyebrow">COSTA DO SAUÍPE & RIO QUENTE</div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${state.view==='users'?btn('new-user','Adicionar pessoa','',true):state.view==='catalog'?`${state.user.can_catalog?btn('classify-selected','Classificar seleção')+btn('add-resource','Novo recurso físico'):''}`:btn('availability','Consultar disponibilidade')+btn('new-booking','＋ Nova solicitação','',true)}</div></div>${state.view==='calendar'?`<section class="agenda-stats"><article class="agenda-stat"><small>Espaços e configurações<br>Catálogo compartilhado</small><strong>${state.catalog.length}</strong></article><article class="agenda-stat"><small>Solicitações no período<br>Conforme os filtros</small><strong>${state.bookings.length}</strong></article></section>`:''}${unvalidated&&state.view==='calendar'?`<div class="notice">${unvalidated} configurações aguardam validação física. A área hachurada significa “a validar”; dias vazios não garantem disponibilidade.</div>`:''}${state.view==='calendar'?calendarView():state.view==='queue'?`<section class="agenda-card">${toolbar(false)}<div class="calendar-caption"><strong>Solicitações por ordem de entrada</strong><span>Sem promoção ou expiração automática</span></div>${bookingList(state.bookings)}</section>`:state.view==='catalog'?catalogView():state.view==='reports'?reportsView():usersView()}<footer class="agenda-footer"><span>Calendário compartilhado · bloqueios por dia inteiro</span><span>2026 — 2028 · ${esc(state.user.name)}</span></footer></main></div></div>`;bindMain();}
function toolbar(withMonth){return `<div class="agenda-toolbar">${withMonth?`<div class="month-navigation">${btn('prev-month','‹','aria-label="Mês anterior"')}<select id="month" aria-label="Mês">${months.map((m,i)=>option(i,m,state.month)).join('')}</select><select id="year" class="year-select" aria-label="Ano">${[2026,2027,2028].map(y=>option(y,y,state.year)).join('')}</select>${btn('next-month','›','aria-label="Próximo mês"')}</div>`:''}<label>Empreendimento<select id="resort">${option('all','Todos',state.resort)}${Object.entries(resorts).map(([k,v])=>option(k,v,state.resort)).join('')}</select></label><label>Situação<select id="status">${option('','Todas',state.status)}${Object.entries(statusNames).map(([k,v])=>option(k,v,state.status)).join('')}</select></label><label class="grow">Pesquisa<input id="search" type="search" placeholder="Espaço, evento ou responsável…" value="${esc(state.search)}"></label>${withMonth?`<div class="view-toggle">${['grid','list'].map(v=>`<button data-action="mode" data-mode="${v}" class="${state.mode===v?'selected':''}">${v==='grid'?'Grade':'Lista'}</button>`).join('')}</div>`:''}</div>`;}
function calendarView(){const relevant=new Set(state.bookings.flatMap(b=>b.allocations.map(a=>a.configuration_id)));const rows=state.calendar.filter(c=>!state.search||normalized(c.name).includes(normalized(state.search))||relevant.has(c.id));return `<section class="agenda-card">${toolbar(true)}<div class="calendar-caption"><strong>${months[state.month]} de ${state.year}</strong><span>${rows.length} espaços/configurações · selecione um dia para consultar</span></div>${state.mode==='list'?bookingList(state.bookings):rows.length?`<div class="calendar-scroll"><table class="calendar-grid"><caption class="sr-only">Ocupação por espaço e dia. A validar não significa livre.</caption><thead><tr><th class="space-cell">Espaço / configuração</th>${state.days.map(d=>{const dt=new Date(`${d}T12:00:00`);return `<th class="${[0,6].includes(dt.getDay())?'weekend':''}">${Number(d.slice(-2))}<small>${dt.toLocaleDateString('pt-BR',{weekday:'short'}).replace('.','')}</small></th>`;}).join('')}</tr></thead><tbody>${rows.map(c=>`<tr><td class="space-cell"><button data-action="space-detail" data-id="${c.id}">${esc(c.name).replaceAll("+","+<wbr>")}</button><small>${c.validated?esc(resortName(c.resort_id)):'○ Composição a validar'}</small></td>${state.days.map(d=>{const cell=c.days[d];return `<td class="${cell.state}"><button class="day-button ${cell.state}" data-action="day" data-id="${c.id}" data-day="${d}" aria-label="${esc(c.name)}, ${fmt(d)}, ${cell.state==='unvalidated'?'a validar':cell.state==='available'?'sem ocupação efetiva':cell.state==='partial'?'ocupação parcial das opções':'ocupado'}${cell.requests.length?`, ${cell.requests.length} solicitações`:''}">${cell.state==='occupied'?'●':cell.state==='partial'?'◐':''}${cell.requests.length?`<span class="request-count">${cell.requests.length}</span>`:''}</button></td>`;}).join('')}</tr>`).join('')}</tbody></table></div>`:'<div class="empty-state"><h3>Nenhum espaço neste filtro</h3><p>Ajuste o empreendimento ou a pesquisa para ver outros espaços.</p></div>'}<div class="legend"><span>▧ Composição a validar</span><span>● Ocupação efetiva</span><span>◐ Algumas composições ocupadas</span><span>Contador amarelo: solicitações pendentes / em espera</span></div></section>`;}
function bookingList(items){if(!items.length)return '<div class="empty-state"><h3>Nenhuma solicitação neste período</h3><p>Ajuste os filtros ou registre uma nova solicitação.</p></div>';return `<div class="booking-list">${items.map(b=>{const a=b.matched_allocations||b.allocations;return `<article class="booking-row"><div><h3>${esc(b.title)}</h3><small>${esc(b.responsible)} · ${esc(b.team_name)}</small><small>Entrada #${b.queue_number}</small></div><div><p>${[...new Set(a.map(x=>x.space_name))].map(esc).join('<br>')}</p></div><div><p>${fmt(a.map(x=>x.start_date).sort()[0])}<br>até ${fmt(a.map(x=>x.end_date).sort().at(-1))}</p></div><div class="row-status">${pill(b.status)}</div>${btn('booking-detail','Consultar',`data-id="${b.id}"`)}</article>`;}).join('')}</div>`;}
function catalogView(){const rows=state.catalog.filter(c=>(state.resort==='all'||c.resort_id===state.resort)&&(!state.search||normalized(c.name).includes(normalized(state.search))||c.source_codes.join(',').includes(state.search)));return `<section class="agenda-card">${toolbar(false)}<div class="calendar-caption"><strong>${rows.length} espaços/configurações</strong><span>${state.sourceCount} itens de origem · 2 serviços excluídos da agenda</span></div>${state.user.can_catalog?`<div class="legend">${btn('sources','Ver itens de origem')}${btn('import','Revisar importação')}${btn('catalog-history','Histórico cadastral')}</div>`:''}<div class="catalog-scroll"><table class="catalog-table"><thead><tr>${state.user.can_catalog?'<th>Selecionar</th>':''}<th>Espaço / código de origem</th><th>Empreendimento</th><th>Validação física</th><th>Ações</th></tr></thead><tbody>${rows.map(c=>`<tr>${state.user.can_catalog?`<td class="selection"><input type="checkbox" data-select="${c.id}" aria-label="Selecionar ${esc(c.name)}"></td>`:''}<td><strong>${esc(c.name)}</strong><small>Cód. ${c.source_codes.join(', ')} · ${esc(c.group_name||'Outros espaços')}</small></td><td>${esc(resortName(c.resort_id))}<small>${esc(c.location)}</small></td><td>${c.validated?'<span class="status-pill status-option">Validada</span>':'<span class="status-pill">A validar</span>'}</td><td><div class="catalog-actions">${btn('space-detail','Detalhes',`data-id="${c.id}"`)}${state.user.can_catalog?btn('topology','Validar composição',`data-id="${c.id}"`):''}</div></td></tr>`).join('')}</tbody></table></div></section>`;}
function reportsView(){return `<section class="agenda-card">${toolbar(false)}<div class="report-filters"><label>De<input id="report-from" type="date" value="${state.reportFrom}" min="2026-01-01" max="2028-12-31"></label><label>Até<input id="report-to" type="date" value="${state.reportTo}" min="2026-01-01" max="2028-12-31"></label>${btn('report-apply','Aplicar período')}${btn('csv','Exportar CSV')}${btn('print','Imprimir / PDF')}</div>${bookingList(state.bookings)}</section>`;}
function usersView(){return `<section class="agenda-card users-table"><div class="legend">${btn('auth-history','Histórico de acessos')}</div>${state.users.map(u=>`<article><div><strong>${esc(u.name)}</strong><p class="form-help">${esc(u.username)} · ${u.team_id==='commercial'?'Comercial MICE':'Operacional'} · ${u.active?'Ativo':'Desativado'}<br>${u.scopes.filter(s=>resorts[s]).map(s=>esc(resorts[s])).join(' · ')||'Nenhum empreendimento'}<br>${[u.can_catalog?'Cadastro':'',u.can_schedule?'Responsável da fila':'',u.can_manage_users?'Administração de acessos':''].filter(Boolean).join(' · ')||'Consulta e edição da própria equipe'}</p></div>${u.id!==state.user.id?`<div class="user-actions">${btn('edit-user','Ajustar acesso',`data-id="${u.id}"`)}<button type="button" class="btn danger" data-action="delete-user" data-id="${u.id}">Excluir pessoa</button></div>`:''}</article>`).join('')}</section>`;}
function bindMain(){for(const [id,key] of [['month','month'],['year','year'],['resort','resort'],['status','status']]){const el=$(`#${id}`);if(el)el.onchange=async()=>{state[key]=['month','year'].includes(key)?Number(el.value):el.value;await refresh();};}const search=$('#search');if(search){let timer;search.oninput=()=>{clearTimeout(timer);timer=setTimeout(async()=>{state.search=search.value;const pos=search.selectionStart;await refresh();const next=$('#search');next?.focus();if(next)next.setSelectionRange(pos,pos);},450);};}}
function allocMarkup(a,index){const c=state.catalog.find(c=>c.id===a.configuration_id);const selected=JSON.stringify([...(a.resources||[])].sort());return `<div class="allocation-row" data-allocation><label class="allocation-space">Espaço<select data-field="configuration_id" required>${option('','Selecione um espaço',a.configuration_id)}${state.catalog.map(c=>option(c.id,c.name,a.configuration_id)).join('')}</select></label><label>Fase<select data-field="phase">${Object.entries(phases).map(([k,v])=>option(k,v,a.phase||'event')).join('')}</select></label><label>Início<input data-field="start_date" type="date" value="${esc(a.start_date)}" min="2026-01-01" max="2028-12-31" required></label><label>Último dia<input data-field="end_date" type="date" value="${esc(a.end_date)}" min="2026-01-01" max="2028-12-31" required></label>${btn('remove-allocation','×','aria-label="Remover período"')}<label class="composition">${c?.validated?'Composição homologada':'Composição pendente de validação'}<select data-field="resources" ${c?.validated?'':'disabled'}>${!c?.validated?option('[]','Composição física a validar','[]'):c.options.map(o=>option(JSON.stringify(o),o.map(resourceName).join(' + '),selected)).join('')}</select></label></div>`;}
function readAllocations(){return [...document.querySelectorAll('[data-allocation]')].map(row=>Object.fromEntries([...row.querySelectorAll('[data-field]')].map(el=>[el.dataset.field,el.dataset.field==='resources'?JSON.parse(el.value||'[]'):el.value])));}
function wireAllocations(){document.querySelectorAll('[data-field="configuration_id"]').forEach(el=>el.onchange=()=>{const row=el.closest('[data-allocation]');const c=state.catalog.find(c=>c.id===el.value);const field=row.querySelector('[data-field="resources"]');field.disabled=!c?.validated;field.innerHTML=c?.validated?c.options.map(o=>option(JSON.stringify(o),o.map(resourceName).join(' + '),JSON.stringify(c.options[0]))).join(''):option('[]','Composição física a validar','[]');row.querySelector('.composition').firstChild.textContent=c?.validated?'Composição homologada':'Composição pendente de validação';});}
function bookingForm(booking=null,configId='',dateValue=''){const dates=range();const allocations=booking?.allocations||[{configuration_id:configId,phase:'event',start_date:dateValue||dates.from,end_date:dateValue||dates.from,resources:state.catalog.find(c=>c.id===configId)?.options[0]||[]}];const states=!booking||['pending','waiting'].includes(booking.status)?['pending','waiting']:booking.status==='option'?['option',...(state.user.can_schedule?['confirmed']:[]),'waiting','pending']:['confirmed','waiting','pending'];if(!modal(booking?'Editar solicitação':'Nova solicitação',`<form id="booking-form"><div class="form-grid"><label>Evento / motivo<input name="title" maxlength="180" required value="${esc(booking?.title||'')}" autofocus></label><label>Responsável<input name="responsible" maxlength="120" required value="${esc(booking?.responsible||state.user.name)}"></label><label>Situação<select name="status">${states.map(s=>option(s,statusNames[s],booking?.status||'pending')).join('')}</select></label><label>Equipe proprietária<input value="${state.user.team_id==='commercial'?'Comercial MICE':'Operacional'}" disabled></label></div><div class="notice">Todos os dias informados são incluídos. Solicitações pendentes e em espera não bloqueiam o espaço. O responsável pela fila pode confirmar a reserva, bloqueando a configuração escolhida em todos os dias informados. Composições físicas ainda não validadas exigem atenção especial.</div><div id="allocations">${allocations.map(allocMarkup).join('')}</div>${btn('add-allocation','＋ Adicionar espaço ou fase')}<label class="full-width">Observações<textarea name="notes" maxlength="4000">${esc(booking?.notes||'')}</textarea></label>${state.user.can_schedule&&(!booking||['pending','waiting'].includes(booking.status))?'<label class="checkbox-line"><input type="checkbox" name="confirm_reservation">Confirmar reserva e bloquear o espaço neste período</label>':''}<div class="form-help">${booking?'Alterar datas/espaços de uma solicitação em espera reposiciona sua entrada na fila.':'A equipe e a autoria são registradas pelo servidor.'}</div><div class="form-error" role="alert"></div></form>`,`${btn('close','Cancelar')}<button class="btn primary" type="submit" form="booking-form">Salvar solicitação</button>`,true))return;wireAllocations();let key=crypto.randomUUID();$('#booking-form').oninput=()=>{key=crypto.randomUUID();modalDirty=true;};bindForm('#booking-form',async fields=>{const payload={...Object.fromEntries(fields),allocations:readAllocations(),...(booking?{version:booking.version}:{})};if(fields.get('confirm_reservation')==='on')payload.status='confirmed';delete payload.confirm_reservation;await repository.save(payload,booking?.id,key);closeModal(true);await refresh();toast(payload.status==='confirmed'?'Reserva confirmada; o espaço está bloqueado no período.':payload.status==='pending'?'Solicitação pendente registrada; a sala ainda não está bloqueada.':'Solicitação salva na base compartilhada.');});}
async function bookingDetail(id){const {booking:b,history}=await request(`/bookings/${id}`);const own=b.team_id===state.user.team_id;const actions=`${own&&b.status!=='cancelled'?btn('edit-booking','Editar',`data-id="${id}"`)+btn('cancel-booking','Cancelar solicitação',`data-id="${id}" data-version="${b.version}"`):''}${state.user.can_schedule&&b.status==='waiting'?btn('promote','Conceder opção prioritária',`data-id="${id}" data-version="${b.version}"`):''}${state.user.can_schedule&&['pending','waiting','option'].includes(b.status)?btn('confirm-booking','Confirmar reserva',`data-id="${id}" data-version="${b.version}"`,true):''}`;modal(esc(b.title),`<dl class="detail-grid"><div><dt>Situação</dt><dd>${pill(b.status)}</dd></div><div><dt>Equipe / responsável</dt><dd>${esc(b.team_name)} · ${esc(b.responsible)}</dd></div><div><dt>Entrada na fila</dt><dd>#${b.queue_number} · ${esc(b.creator_name)}</dd></div><div><dt>Observações</dt><dd>${esc(b.notes)||'—'}</dd></div></dl><div class="notice neutral-notice">${b.allocations.map(a=>`${esc(a.space_name)} · ${phases[a.phase]}<br>${fmt(a.start_date)} a ${fmt(a.end_date)} · ${esc(resortName(a.resort_id))}${a.resources.length?`<br>${a.resources.map(resourceName).map(esc).join(' + ')}`:''}`).join('<hr>')}</div><h3>Histórico da solicitação</h3>${historyMarkup(history)}`,actions,true);}
function cancelForm(id,version){
  if(!modal('Cancelar solicitação',`<form id="cancel-form"><p>O cancelamento libera todos os espaços e dias desta solicitação. O histórico será preservado e a fila continuará aguardando promoção manual.</p><label>Motivo do cancelamento<textarea name="reason" required maxlength="600"></textarea></label><div class="form-error" role="alert"></div></form>`,`${btn('close','Voltar')}<button type="submit" form="cancel-form" class="btn primary">Confirmar cancelamento</button>`))return;
  bindForm('#cancel-form',async fields=>{await request(`/bookings/${id}/cancel`,{method:'POST',body:{version,reason:fields.get('reason')}});closeModal(true);await refresh();toast('Cancelado; nenhum item em espera foi promovido automaticamente.');});
}
function confirmBookingForm(id,version){
  if(!modal('Confirmar reserva',`<form id="confirmation-form"><p>Esta confirmação bloqueia todos os espaços e dias da solicitação. Se algum espaço já estiver reservado, nada será confirmado.</p><div class="notice">Para composições ainda não validadas, o bloqueio cobre a configuração escolhida. Sobreposições com outras configurações dependem da validação física pela operação.</div><label class="checkbox-line"><input type="checkbox" name="confirmed" required>Confirmo o bloqueio de todos os espaços e dias desta solicitação.</label><div class="form-error" role="alert"></div></form>`,`${btn('close','Voltar')}<button type="submit" form="confirmation-form" class="btn primary">Confirmar reserva</button>`))return;
  bindForm('#confirmation-form',async()=>{await request(`/bookings/${id}/confirm`,{method:'POST',body:{version}});closeModal(true);await refresh();toast('Reserva confirmada; os espaços foram bloqueados no período.');});
}
function historyMarkup(history){const names={create:'Solicitação criada',update:'Solicitação alterada',cancel:'Solicitação cancelada',promote:'Opção prioritária concedida',classify:'Empreendimento classificado',validate_topology:'Composição validada',validate:'Recurso físico validado',import:'Catálogo importado'};return `<div class="history-list">${history.map(h=>`<article><strong>${esc(names[h.action]||h.action)}</strong><small>${esc(h.actor_name||'Carga inicial')} · ${new Date(h.occurred_at).toLocaleString('pt-BR')}</small>${h.note?`<p>${esc(h.note)}</p>`:''}</article>`).join('')||'<p>Nenhuma alteração registrada.</p>'}</div>`;}
function authEventsMarkup(events){const names={login:'Entrada',logout:'Saída',sso_start:'Início do login corporativo',sso_callback:'Retorno do login corporativo',access_denied:'Acesso negado',access_change:'Acesso alterado',password_change:'Senha local alterada',identity_link:'Identidade vinculada'};const results={accepted:'Aceito',rejected:'Recusado',started:'Iniciado',rate_limited:'Limite de tentativas'};return `<div class="history-list">${events.map(e=>`<article><strong>${esc(names[e.event_type]||e.event_type)} · ${esc(results[e.result]||e.result)}</strong><small>${esc(e.user_name||'Pessoa não identificada')} · ${new Date(e.occurred_at).toLocaleString('pt-BR')}</small>${e.reason?`<p>${esc(e.reason)}</p>`:''}${e.request_id?`<small>Referência: ${esc(e.request_id)}</small>`:''}</article>`).join('')||'<p>Nenhum evento registrado.</p>'}</div>`;}
function spaceDetail(id){const c=state.catalog.find(c=>c.id===id);const technical=Object.entries(c.technical).filter(([,v])=>v&&v!=='-');modal(esc(c.name),`<dl class="detail-grid"><div><dt>Empreendimento</dt><dd>${esc(resortName(c.resort_id))}</dd></div><div><dt>Localização</dt><dd>${esc(c.location)||'Não informada'}</dd></div><div><dt>Fonte</dt><dd>Códigos ${c.source_codes.join(', ')}</dd></div><div><dt>Composição</dt><dd>${c.validated?c.options.map(o=>o.map(resourceName).map(esc).join(' + ')).join('<br>'):'A validar'}</dd></div></dl><div class="notice">${esc(c.notes).replaceAll('\n','<br>')}</div>${technical.length?`<h3>Dados técnicos da fonte</h3><p class="form-help">Valores de referência; campos ausentes não foram preenchidos.</p><dl class="detail-grid">${technical.map(([k,v])=>`<div><dt>${esc({medidas:'Medidas',area_m2:'Área (m²)',pe_direito:'Pé-direito',auditorio:'Auditório',escolar_espinha:'Escolar / Espinha',u:'U',banquete:'Banquete'}[k]||k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>`:''}`,`${btn('new-for-space','Nova solicitação',`data-id="${id}"`,true)}${state.user.can_catalog?btn('topology','Validar composição',`data-id="${id}"`):''}`,true);}
function dayDetail(id,d){const c=state.calendar.find(c=>c.id===id);const cell=c.days[d];const ids=[...new Set([...cell.bookings,...cell.requests])];const data=new Map([...state.occupying,...state.bookings].map(b=>[b.id,b]));modal(`${esc(c.name)} · ${fmt(d)}`,`${cell.state==='unvalidated'?'<div class="notice">A composição física ainda não foi validada. Uma nova solicitação ficará pendente, sem garantia de ocupação.</div>':''}${cell.restricted?'<div class="notice">Existe ocupação com detalhes restritos ao seu acesso.</div>':''}${bookingList(ids.map(i=>data.get(i)).filter(Boolean))}`,btn('new-for-day','Nova solicitação',`data-id="${id}" data-day="${d}"`,true),true);}
function classifySelected(){const ids=[...document.querySelectorAll('[data-select]:checked')].map(e=>e.dataset.select);if(!ids.length){toast('Selecione os espaços na tabela.',true);return;}modal('Classificar empreendimento',`<form id="classification-form"><p>Esta alteração mantém os mesmos espaços, bloqueios e histórico.</p><div class="notice neutral-notice">${ids.map(id=>esc(state.catalog.find(c=>c.id===id).name)).join('<br>')}</div><label>Empreendimento<select name="resort_id" required><option value="" disabled selected>Selecione o empreendimento</option>${['cs','rq'].filter(s=>state.user.scopes.includes(s)).map(s=>option(s,resorts[s],'')).join('')}</select></label><label>Hotel, ala ou localização<input name="location" maxlength="150"></label><label>Referência / motivo da classificação<textarea name="reason" required maxlength="500"></textarea></label><div class="form-error"></div></form>`,`${btn('close','Cancelar')}<button class="btn primary" form="classification-form" type="submit">Confirmar classificação</button>`);bindForm('#classification-form',async fields=>{const body=Object.fromEntries(fields);body.changes=ids.map(id=>({id,version:state.catalog.find(c=>c.id===id).version}));await request('/catalog/classify',{method:'POST',body});closeModal(true);await refresh();toast('Classificação atualizada; os registros foram preservados.');});}
function optionEditor(selected=[],n=1){return `<fieldset class="resource-option"><legend>Conjunto permitido ${n}</legend>${state.resources.map(r=>`<label><input type="checkbox" value="${r.id}" ${selected.includes(r.id)?'checked':''}>${esc(r.name)} <small>· ${esc(resortName(r.resort_id))}</small></label>`).join('')}</fieldset>`;}
function topologyForm(id){const c=state.catalog.find(c=>c.id===id);const sets=c.options.length?c.options:c.suggested_options.length?c.suggested_options:[[]];modal(`Validar composição · ${esc(c.name)}`,`<form id="topology-form"><div class="notice">As sugestões da fonte não são homologação. Confirme os recursos físicos com a operação antes de salvar. Opções diferentes devem representar conjuntos realmente permitidos.${c.module_count?` Cada conjunto exige ${c.module_count} recursos.`:''}</div><div id="physical-options">${sets.map((s,i)=>optionEditor(s,i+1)).join('')}</div>${c.kind==='espaco_sem_composicao_explicita'?'':btn('add-physical-option','＋ Outro conjunto permitido')}<label>Referência da validação<textarea name="reason" required maxlength="600" placeholder="Quem confirmou, data e documento ou orientação utilizada"></textarea></label><label class="checkbox-line"><input type="checkbox" name="attested" required>Confirmo que a composição física foi verificada.</label><div class="form-error"></div></form>`,`${btn('close','Cancelar')}<button class="btn primary" form="topology-form" type="submit">Salvar validação</button>`,true);bindForm('#topology-form',async fields=>{const options=[...document.querySelectorAll('.resource-option')].map(s=>[...s.querySelectorAll('input:checked')].map(i=>i.value));await request(`/catalog/${id}/topology`,{method:'POST',body:{version:c.version,options,attested:fields.get('attested')==='on',reason:fields.get('reason')}});closeModal(true);await refresh();toast('Composição homologada. Solicitações pendentes não foram promovidas automaticamente.');});}
function resourceForm(){modal('Cadastrar recurso físico',`<form id="resource-form"><div class="notice">Use apenas o nome identificado pela operação. Não crie uma nova sala para cada variante de climatização ou fase.</div><label>Nome oficial do módulo / recurso<input name="name" required maxlength="200"></label><label>Empreendimento<select name="resort_id" required><option value="" disabled selected>Selecione o empreendimento</option>${Object.entries(resorts).filter(([k])=>state.user.scopes.includes(k)).map(([k,v])=>option(k,v,'')).join('')}</select></label><label>Localização<input name="location" maxlength="150"></label><label>Referência da identificação<textarea name="evidence" required maxlength="600"></textarea></label><div class="form-error"></div></form>`,`${btn('close','Cancelar')}<button type="submit" form="resource-form" class="btn primary">Cadastrar recurso</button>`);bindForm('#resource-form',async f=>{const body=Object.fromEntries(f);await request('/resources',{method:'POST',body});closeModal(true);await refresh();toast('Recurso cadastrado para revisão das composições.');});}
function availabilityForm(){
  const r=range();
  modal('Consultar disponibilidade',`<form id="availability-form"><div class="form-grid"><label>Primeiro dia<input name="from" type="date" min="2026-01-01" max="2028-12-31" value="${r.from}" required></label><label>Último dia<input name="to" type="date" min="2026-01-01" max="2028-12-31" value="${r.to}" required></label></div><p class="form-help">A consulta separa solicitações sem bloqueio da ocupação efetiva. A fila é verificada ao conceder uma opção.</p><div class="form-error"></div><button class="btn primary" type="submit">Consultar período</button></form><div id="availability-results" class="availability-results"></div>`,'',true);
  bindForm('#availability-form',async fields=>{
    const q=new URLSearchParams({...Object.fromEntries(fields),resort:state.resort});
    const {results}=await request(`/availability?${q}`);
    $('#availability-results').innerHTML=results.map(result=>{
      const requests=[];
      if(result.pending_count)requests.push(`${result.pending_count} solicitaç${result.pending_count===1?'ão':'ões'} pendente${result.pending_count===1?'':'s'}`);
      if(result.waiting_count)requests.push(`${result.waiting_count} em espera`);
      const status=result.available===null?'Composição a validar':result.available?'Sem ocupação efetiva':'Ocupado no período';
      const periodNames={pending:'Solicitação pendente',waiting:'Em espera',option:'Opção prioritária',confirmed:'Reserva confirmada'};
      const periods=(result.periods||[]).map(p=>`<small class="availability-period ${['option','confirmed'].includes(p.status)?'occupied-period':''}">${esc(periodNames[p.status]||p.status)}${p.related?' em configuração compartilhada':''}: ${fmt(p.start_date)}${p.start_date===p.end_date?'':` a ${fmt(p.end_date)}`} · ${esc(phases[p.phase]||p.phase)}</small>`).join('');
      return `<div class="availability-item"><span>${esc(result.name)}${requests.length?`<small class="availability-request">${esc(requests.join(' · '))} · ainda não bloqueia a sala</small>`:''}${periods}</span><span class="status-pill ${result.available?'status-option':''}">${status}</span></div>`;
    }).join('');
    modalDirty=false;
  });
}
function deleteUserForm(user){if(!user)return;modal('Excluir pessoa',`<p><strong>${esc(user.name)}</strong> (${esc(user.username)}) perderá o acesso imediatamente e sairá da lista de pessoas.</p><p>As solicitações e o histórico de auditoria serão preservados. Esta ação não pode ser desfeita.</p>`,`${btn('close','Voltar')}<button type="button" class="btn danger" data-action="confirm-delete-user" data-id="${user.id}">Confirmar exclusão</button>`);}
function userForm(user=null){const scope=user?.scopes||['cs','rq'];modal(user?'Ajustar acesso':'Adicionar pessoa',`<form id="user-form">${!user?'<div class="form-grid"><label>Nome<input name="name" required maxlength="120"></label><label>Usuário<input name="username" required minlength="3" maxlength="64"></label>'+(state.authMode==='entra'?'<label>Object ID no Microsoft Entra ID<input name="entra_object_id" required placeholder="xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx"></label>':passwordField('Senha inicial individual','password','new-password',15,128))+'<label>Equipe<select name="team_id"><option value="commercial">Comercial MICE</option><option value="operations">Operacional</option></select></label></div>':`<p class="review-name">${esc(user.name)}</p><label class="checkbox-line"><input type="checkbox" name="active" ${user.active?'checked':''}>Conta ativa</label>`}<h3>Escopo de consulta</h3>${Object.entries(resorts).map(([s,label])=>`<label class="checkbox-line"><input type="checkbox" name="scopes" value="${s}" ${scope.includes(s)?'checked':''}>${label}</label>`).join('')}<h3>Responsabilidades adicionais</h3><div class="permission-grid">${[['can_catalog','Revisar cadastros e composições'],['can_schedule','Conceder prioridade na fila'],['can_manage_users','Administrar pessoas e acessos']].map(([k,l])=>`<label class="checkbox-line"><input type="checkbox" name="${k}" ${user?.[k]?'checked':''}>${l}</label>`).join('')}</div><div class="notice">A responsabilidade pela fila permite conceder a opção prioritária a outra equipe. Ela não permite editar o evento nem cancelar o bloqueio dessa equipe.</div><div class="form-error"></div></form>`,`${user?`<button type="button" class="btn danger delete-user-modal" data-action="delete-user" data-id="${user.id}">Excluir pessoa</button>`:''}${btn('close','Cancelar')}<button class="btn primary" form="user-form" type="submit">Salvar acesso</button>`,true);bindForm('#user-form',async f=>{const body={...Object.fromEntries(f),scopes:f.getAll('scopes')};for(const k of ['can_catalog','can_schedule','can_manage_users','active'])body[k]=f.get(k)==='on';if(user)body.version=user.version;await request(user?`/users/${user.id}`:'/users',{method:user?'PUT':'POST',body});closeModal(true);await refresh();toast('Acesso salvo.');});}
function passwordForm(){modal('Alterar minha senha',`<form id="password-form">${passwordField('Senha atual','current_password','current-password',0,256)}${passwordField('Nova senha','password','new-password',15,128)}<p class="form-help">A nova senha deve ter de 15 a 128 caracteres.</p><div class="form-error"></div></form>`,`${btn('close','Cancelar')}<button type="submit" form="password-form" class="btn primary">Alterar senha</button>`);bindForm('#password-form',async f=>{await request('/password',{method:'POST',body:Object.fromEntries(f)});closeModal(true);toast('Senha alterada. Outras sessões precisarão entrar novamente.');});}
function printReport(){const rows=state.bookings.flatMap(b=>(b.matched_allocations||b.allocations).map(a=>`<tr><td>${esc(b.title)}</td><td>${esc(resortName(a.resort_id))}</td><td>${esc(a.space_name)}</td><td>${phases[a.phase]}</td><td>${fmt(a.start_date)} — ${fmt(a.end_date)}</td><td>${statusNames[b.status]}</td><td>${esc(b.team_name)} / ${esc(b.responsible)}</td></tr>`));$('#print-area').innerHTML=`<header>Costa do Sauípe & Rio Quente · Agenda de espaços</header><h1>Relatório de bloqueios</h1><p class="report-meta">${fmt(state.reportFrom)} a ${fmt(state.reportTo)} · ${state.resort==='all'?'Todos os empreendimentos':resortName(state.resort)} · ${state.status?statusNames[state.status]:'Todas as situações'}${state.search?` · Pesquisa: ${esc(state.search)}`:''}</p><p>${rows.length} períodos encontrados.</p><table><thead><tr>${['Evento','Empreendimento','Espaço','Fase','Período','Situação','Equipe / responsável'].map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table>`;window.print();}
async function importForm(){modal('Revisar importação da lista',`<p>A importação valida a lista inteira antes de gravar e preserva o cadastro já revisado.</p><input id="catalog-file" type="file" accept=".json,application/json"><div id="import-preview"></div>`);$('#catalog-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>3*1024*1024)throw new Error('O arquivo deve ter até 3 MB.');const catalog=JSON.parse(await file.text());const result=await request('/catalog/import',{method:'POST',body:{catalog}});$('#import-preview').innerHTML=`<div class="notice neutral-notice">${result.items} itens · ${result.new} novos · 2 serviços mantidos apenas como referência.</div>${btn('confirm-import',result.already_imported?'Catálogo já importado':'Confirmar carga',result.already_imported?'disabled':'',true)}`;$('#import-preview button').onclick=async()=>{try{await request('/catalog/import',{method:'POST',body:{catalog,confirm:true}});closeModal(true);await refresh();toast('Catálogo importado sem duplicação.');}catch(error){errorView(error);}};}catch(error){errorView(error);}};}
document.addEventListener('click',async e=>{const target=e.target.closest('[data-action]');if(!target||target.disabled)return;const action=target.dataset.action,id=target.dataset.id;try{if(action==='toggle-password'){const input=document.getElementById(target.getAttribute('aria-controls'));if(input){const visible=input.type==='password';input.type=visible?'text':'password';target.textContent=visible?'Ocultar':'Mostrar';target.setAttribute('aria-label',visible?'Ocultar senha':'Mostrar senha');target.setAttribute('aria-pressed',String(visible));}}else if(action==='retry')await boot();else if(action==='close')closeModal();else if(action==='refresh')await refresh();else if(action==='logout'){if($('#editor').open&&!closeModal())return;await repository.logout();state.user=null;await boot();}else if(action==='navigate'){if($('#editor').open&&!closeModal())return;state.view=target.dataset.view;state.status='';state.search='';await refresh();}else if(action==='mode'){state.mode=target.dataset.mode;render();}else if(action==='prev-month'||action==='next-month'){const d=new Date(state.year,state.month+(action==='next-month'?1:-1),1);if(d.getFullYear()<2026||d.getFullYear()>2028)return;state.year=d.getFullYear();state.month=d.getMonth();await refresh();}else if(action==='new-booking')bookingForm();else if(action==='new-for-space')bookingForm(null,id);else if(action==='new-for-day')bookingForm(null,id,target.dataset.day);else if(action==='booking-detail')await bookingDetail(id);else if(action==='edit-booking'){const {booking}=await request(`/bookings/${id}`);bookingForm(booking);}else if(action==='cancel-booking'){cancelForm(id,Number(target.dataset.version));}else if(action==='confirm-booking')confirmBookingForm(id,Number(target.dataset.version));else if(action==='promote'){target.disabled=true;await request(`/bookings/${id}/promote`,{method:'POST',body:{version:Number(target.dataset.version)}});closeModal(true);await refresh();toast('Opção prioritária concedida para todo o conjunto.');}else if(action==='space-detail')spaceDetail(id);else if(action==='day')dayDetail(id,target.dataset.day);else if(action==='add-allocation'){const first=readAllocations()[0]||{};$('#allocations').insertAdjacentHTML('beforeend',allocMarkup({start_date:first.start_date||range().from,end_date:first.end_date||range().from}));wireAllocations();$('#booking-form').dispatchEvent(new Event('input',{bubbles:true}));}else if(action==='remove-allocation'){if(document.querySelectorAll('[data-allocation]').length<=1){toast('Mantenha ao menos um período.',true);return;}target.closest('[data-allocation]').remove();$('#booking-form').dispatchEvent(new Event('input',{bubbles:true}));}else if(action==='classify-selected')classifySelected();else if(action==='topology')topologyForm(id);else if(action==='add-physical-option'){$('#physical-options').insertAdjacentHTML('beforeend',optionEditor([],document.querySelectorAll('.resource-option').length+1));modalDirty=true;}else if(action==='add-resource')resourceForm();else if(action==='availability')availabilityForm();else if(action==='new-user')userForm();else if(action==='edit-user')userForm(state.users.find(u=>u.id===id));else if(action==='delete-user')deleteUserForm(state.users.find(u=>u.id===id));else if(action==='confirm-delete-user'){const user=state.users.find(u=>u.id===id);if(!user)return;target.disabled=true;await request(`/users/${id}`,{method:'DELETE',body:{version:user.version}});closeModal(true);await refresh();toast('Pessoa excluída e acesso encerrado.');}else if(action==='password')passwordForm();else if(action==='report-apply'){state.reportFrom=$('#report-from').value;state.reportTo=$('#report-to').value;await refresh();}else if(action==='csv'){const response=await fetch(`/api/reports.csv?${queryString()}`,{credentials:'same-origin'});if(!response.ok)throw new Error((await response.json()).error);const url=URL.createObjectURL(await response.blob());const a=document.createElement('a');a.href=url;a.download='calendario-salas.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}else if(action==='print')printReport();else if(action==='import')await importForm();else if(action==='catalog-history'){const data=await request('/audit/catalog');modal('Histórico cadastral',historyMarkup(data.history),'',true);}else if(action==='auth-history'){const data=await request('/audit/auth');modal('Histórico de acessos',authEventsMarkup(data.events),'',true);}else if(action==='sources'){const data=await request('/catalog/sources');modal('125 itens da fonte',`<div class="notice">Linhas de origem não equivalem a espaços físicos independentes. Serviços não são reserváveis.</div><div class="catalog-scroll"><table class="catalog-table"><thead><tr><th>Código</th><th>Nome original</th><th>Tratamento</th></tr></thead><tbody>${data.items.map(i=>`<tr><td>${i.code}</td><td>${esc(i.name)}</td><td>${i.kind==='servico'?'Serviço · fora da agenda':i.kind==='variante_utilizacao_arena'?'Variante de utilização':i.kind==='combinacao_ou_configuracao'?'Configuração':'Espaço candidato'}</td></tr>`).join('')}</tbody></table></div>`,'',true);}}catch(error){errorView(error);}finally{if(target.isConnected)target.disabled=false;}});
window.addEventListener('beforeunload',e=>{if(modalDirty){e.preventDefault();e.returnValue='';}});
window.addEventListener('focus',()=>refresh(true));
setInterval(()=>refresh(true),20000);
await boot();
